with scored as (select *, lead(discount_pct, 2) over (order by starts_on, id) as next_discount_pct, percent_rank() over (partition by channel order by discount_pct desc) as discount_pct_percent_rank, dense_rank() over (order by discount_pct desc) as discount_pct_dense_rank from promotions), metrics as (select *, avg(next_discount_pct) over (partition by channel order by ends_on, id rows between 5 preceding and current row) as next_discount_pct_avg_5, first_value(channel) ignore nulls over (partition by channel order by starts_on, id rows between unbounded preceding and current row) as first_known_channel, count(discount_pct_dense_rank) over (partition by promo_code, channel) as promo_code_count_discount_pct_dense_rank, avg(discount_pct_dense_rank) over (partition by promo_code order by ends_on, id rows between 3 preceding and 1 preceding) as discount_pct_dense_rank_avg_3_prior, ntile(10) over (partition by promo_code, channel order by discount_pct_dense_rank, id) as discount_pct_dense_rank_bucket from scored), scored_promotions as (select *, avg(next_discount_pct) over (partition by promo_code, channel order by discount_pct_dense_rank, id rows between 3 preceding and 1 preceding) as next_discount_pct_avg_3_prior, avg(discount_pct_dense_rank) over (order by starts_on, id rows between 2 preceding and current row) as discount_pct_dense_rank_avg_2, ntile(4) over (partition by channel order by promo_code_count_discount_pct_dense_rank desc, id) as promo_code_count_discount_pct_dense_rank_bucket, last_value(next_discount_pct, true) over (partition by channel order by next_discount_pct_avg_5, id rows between unbounded preceding and current row) as last_known_next_discount_pct, avg(promo_code_count_discount_pct_dense_rank) over (partition by promo_code order by next_discount_pct, id rows between 3 preceding and current row) as promo_code_count_discount_pct_dense_rank_avg_3 from metrics), deduped as (select *, row_number() over (partition by promo_code order by next_discount_pct_avg_5 nulls first, id) as row_num from scored_promotions qualify row_num = 1) select id, promo_code, starts_on, ends_on, discount_pct, next_discount_pct, discount_pct_percent_rank, discount_pct_dense_rank, first_known_channel from deduped
